#pragma once
static const char* phoneRemotePage=R"SGREMOTE(<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Slice Remote"><title>Slice Remote</title><style>
*{box-sizing:border-box}body{margin:0;background:#202020;color:#eee;font:17px system-ui;padding:max(20px,env(safe-area-inset-top)) 16px}header{display:flex;justify-content:space-between;align-items:center}h1{font-size:24px}button{background:#383838;border:1px solid #666;border-radius:10px;color:white;padding:14px;font:inherit;touch-action:manipulation}article{background:#2d2d2d;border-radius:14px;padding:16px;margin:14px 0}.name{font-size:14px;color:#bbb}.file{margin:12px 0;overflow-wrap:anywhere;font-weight:600}.buttons{display:flex;gap:10px}.buttons button{flex:1}.fav{background:#754039}.on{color:#ffdc72}small{display:block;color:#bbb;font-size:12px;margin-top:14px}#status{color:#aaa;font-size:13px}input{font:inherit;width:100%;background:transparent;color:white;border:0;padding:5px 0}label{display:block;padding:12px 0}a{color:#a9dade}details{font-size:13px;color:#bbb;margin-top:20px}</style></head><body>
<header><h1>Slice Remote</h1><button id="edit">Edit</button></header><div id="status">Connecting…</div><div id="rows"></div><details><summary>Connect your iPhone</summary><p id="addresses"></p><p>Use the same Wi-Fi as your Mac. Open this address in Safari, then Share → Add to Home Screen. Keep this private pairing address to yourself.</p></details>
<script>
const base=location.pathname.replace(/\/$/,''), rows=document.querySelector('#rows'), status=document.querySelector('#status');let editing=false,last=[],busy=false,prefs;try{prefs=JSON.parse(localStorage.getItem('sliceRemote')||'{}')}catch{prefs={}}const save=()=>localStorage.setItem('sliceRemote',JSON.stringify(prefs));
function el(tag,text,cls){let n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function draw(){rows.replaceChildren();for(const r of last){let pref=prefs[r.id]||{};if(pref.hidden&&!editing)continue;let card=el('article');if(editing){let lab=el('label'),check=el('input');check.type='checkbox';check.style.width='auto';check.checked=!pref.hidden;check.onchange=()=>{prefs[r.id]={...prefs[r.id],hidden:!check.checked};save()};lab.append(check,document.createTextNode(' Show '+r.label));card.append(lab);let name=el('input');name.placeholder=r.label;name.value=pref.name||'';name.onchange=()=>{prefs[r.id]={...prefs[r.id],name:name.value};save()};card.append(name)}else{card.append(el('div',pref.name||r.label,'name'),el('div',r.file||'No file loaded','file'));let bar=el('div',undefined,'buttons');for(const [cmd,title] of [['prev','◀'],['fav',r.favourite?'★':'☆'],['next','▶']]){let b=el('button',title,cmd==='fav'?'fav'+(r.favourite?' on':''):'');b.disabled=!r.file||(cmd!=='fav'&&!r.navigate);b.setAttribute('aria-label',cmd==='fav'?'Favourite':cmd==='prev'?'Previous':'Next');b.onclick=()=>send(r,cmd);bar.append(b)}card.append(bar);if(r.busy)card.append(el('small','Loading…'))}rows.append(card)}if(!rows.children.length)rows.append(el('p',last.length?'All rows hidden. Tap Edit to show them.':'Load a sound in Slice Groups.'))}
async function send(row,cmd){if(busy)return;busy=true;try{let res=await fetch(base+'/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({instance:row.instance,group:row.group,command:cmd,file:row.key})});if(!res.ok)throw Error();status.textContent=cmd==='fav'?'Favourite saved':'Loading…'}catch{status.textContent='Command failed. Check connection.'}finally{busy=false;poll()}}
async function poll(){try{let res=await fetch(base+'/state',{cache:'no-store'});if(!res.ok)throw Error();let data=await res.json();last=data.rows;status.textContent='Connected · '+data.instances+' instance'+(data.instances===1?'':'s');document.querySelector('#addresses').replaceChildren(...data.addresses.flatMap(a=>{let link=el('a',a);link.href=a;return[link,el('br')]}));if(!editing)draw()}catch{status.textContent='Disconnected · reconnecting…'}}document.querySelector('#edit').onclick=()=>{editing=!editing;document.querySelector('#edit').textContent=editing?'Done':'Edit';draw()};setInterval(()=>{if(!document.hidden)poll()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});poll();
</script></body></html>
)SGREMOTE";
